fn git_file<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    path: &str,
) -> Result<String, GraphError> {
    let object = object_at(commit, path);
    git_stdout(runner, root, &["show", &object])
}

/// `rev:./path`: git resolves a bare `rev:path` from the repository top, not the workspace directory.
pub(super) fn object_at(rev: &str, path: &str) -> String {
    format!("{rev}:./{path}")
}

pub(super) fn normalized_git_path(path: &std::path::Path) -> Result<String, GraphError> {
    let path = callisto_model::workspace_relative(path)?;
    let path = path.to_string_lossy().into_owned();
    if path.contains(['\0', '\n', '\r']) {
        return Err(command_malformed_output(
            "git",
            &["cat-file", "--batch"],
            "workspace path contains a forbidden control character",
        ));
    }
    Ok(path)
}

fn historical_manifest_error(error: callisto_model::ManifestError) -> GraphError {
    match error {
        callisto_model::ManifestError::InvalidVersion { source, .. } => GraphError::from(source),
        other => command_malformed_output("git", &["cat-file", "--batch"], other.to_string()),
    }
}

#[cfg(test)]
fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
    // `canonical_manifests()` only builds Canonical decls for formats that have a canonical format; a miss breaks that invariant.
    let format = ecosystem
        .canonical_manifest_format()
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!(
                "canonical manifest `{path}` has ecosystem `{}`, which has no canonical manifest format",
                ecosystem.prefix()
            ),
        })?;
    let version = callisto_manifests::read_effective_version(
        format,
        source,
        std::path::Path::new(path),
        &mut callisto_manifests::WorkspaceReads::default(),
        |_| Ok::<_, callisto_model::ManifestError>(None),
    )
    .map_err(historical_manifest_error)?
    .ok_or_else(|| {
        command_malformed_output(
            "git",
            &["cat-file", "--batch"],
            format!("manifest `{path}` has no effective declared version"),
        )
    })?;
    Ok(version.version)
}

/// Every path in `paths` at `commit`, in one `git cat-file --batch`.
fn batch_manifest_blobs_at<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    paths: &[&str],
) -> Result<Vec<BatchBlob>, GraphError> {
    let objects: Vec<String> = paths.iter().map(|path| object_at(commit, path)).collect();
    batch_blobs(runner, root, &objects)
}

/// The manifests of one commit: those fetched up front in one batch, and any other fetched on first ask. A package that
/// names its workspace with `package.workspace` can name a different one at each of two commits, so the second commit's
/// workspace manifest is not among those fetched for the first.
struct CommitBlobs<'a, R: CommandRunner> {
    runner: &'a R,
    root: &'a std::path::Path,
    commit: &'a str,
    blobs: std::cell::RefCell<std::collections::BTreeMap<String, BatchBlob>>,
}

impl<'a, R: CommandRunner> CommitBlobs<'a, R> {
    fn new(runner: &'a R, root: &'a std::path::Path, commit: &'a str, paths: &[&str], blobs: Vec<BatchBlob>) -> Self {
        CommitBlobs {
            runner,
            root,
            commit,
            blobs: std::cell::RefCell::new(paths.iter().map(|path| (*path).to_owned()).zip(blobs).collect()),
        }
    }

    /// The text of `path` at the commit, `None` when it has none there.
    fn text(&self, path: &str) -> Result<Option<String>, GraphError> {
        if !self.blobs.borrow().contains_key(path) {
            let fetched = batch_manifest_blobs_at(self.runner, self.root, self.commit, &[path])?;
            let blob = fetched.into_iter().next().unwrap_or(BatchBlob::Missing);
            self.blobs.borrow_mut().insert(path.to_owned(), blob);
        }
        Ok(match &self.blobs.borrow()[path] {
            BatchBlob::Blob(text) => Some(text.clone()),
            BatchBlob::Missing => None,
        })
    }
        }
    }

    Ok(())
}

/// Reads every canonical manifest at `head` in one `git cat-file --batch`, so the version reads that follow cost no
/// process each. A failed batch is not an error: those reads then run one at a time, as they always could.
fn prefetch_head_manifests<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    head: &str,
    texts: &ManifestTexts,
) -> Result<(), GraphError> {
    let mut paths = BTreeSet::new();
    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
    }
    let objects: Vec<String> = paths
        .iter()
        .map(|path| super::release_decision::object_at(head, path))
        .collect();
    let Ok(blobs) = batch_blobs(ws.runner, &ws.root, &objects) else {
        return Ok(());
    };
    let mut texts = texts.borrow_mut();
    for (path, blob) in paths.into_iter().zip(blobs) {
        texts.insert(
            path,
            match blob {
                BatchBlob::Blob(text) => Some(text),
                BatchBlob::Missing => None,
            },
        );
    }
    Ok(())
}

/// True when an untracked or tracked changeset remains in the configured directory on disk.
fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
) -> Result<bool, GraphError> {
    let dir = ws.root.join(&ws.config.changesets_dir);
    let files = crate::aggregate::list_changeset_files(&dir).map_err(|error| GraphError::ApplyIo {
        path: ws.config.changesets_dir.clone(),
        message: error.to_string(),
    })?;
    Ok(!files.is_empty())
}

/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    head: &str,
    changed: &SourceChanges,
    sources: &mut HashMap<std::path::PathBuf, Vec<String>>,
) -> Result<BTreeSet<String>, GraphError> {
    let mut paths = BTreeSet::new();
    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
        paths.extend(version_sources(ws, head, changed, decl, sources)?);
    }
    // The index-versus-HEAD diff `SourceChanges` already read answers this for every path at once.
    Ok(paths.into_iter().filter(|path| changed.staged.contains(path)).collect())
}

/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    spec: &str,
) -> Result<bool, GraphError> {
    let output = ws
        .runner
        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
        .map_err(GraphError::Command)?;
    match output.exit_code {
        Some(0) => Ok(true),
        Some(1) => Ok(false),
        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code,
            stderr: output.stderr,
        })),
    }
}

/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    head: &str,
) -> Result<bool, GraphError> {
    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
    let spec = super::release_decision::object_at(head, &dir);
    if !head_object_exists(ws, &spec)? {
        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
        return Ok(false);
    }
    let output = ws
        .runner
        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
        .map_err(GraphError::Command)?;
    if !output.success() {
        return Err(GraphError::Command(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.stderr,
        }));
    }
    Ok(output.stdout.lines().any(|name| {
        let name = name.trim();
        name.ends_with(".md") && name != "README.md"
    }))
}

fn manifest_blob_at<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    head: &str,
    path: &str,
) -> Result<Option<String>, GraphError> {
    let spec = super::release_decision::object_at(head, path);
    if !head_object_exists(ws, &spec)? {
        return Ok(None);
    }
    let output = ws
        .runner
        .run("git", &["show", &spec], &ws.root)
        .map_err(GraphError::Command)?;
    if !output.success() {
        return Err(GraphError::Command(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.stderr,
        }));
    }
    Ok(Some(output.stdout))
}

