/// A `pyproject.toml` manifest editor supporting PEP 621, Poetry, and Flit schemas with 100% CST comment preservation.
pub struct PyprojectToml {
    path: PathBuf,
    absolute: PathBuf,
    role: ManifestRole,
    document: toml_edit::DocumentMut,
