                .parse()
                .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
                    path: rel_path.clone(),
                    format: ManifestFormat::PyprojectToml,
                    message: e.to_string(),
                })?;

        Ok(Self {
            path: rel_path,
            absolute: abs_path,
            role: decl.role.clone(),
            document: doc,
            fingerprint,
        })
    }

