    /// The text of `path` (relative to this root) in `rev`'s tree, decoded lossily; `None` when it is absent.
    pub fn read_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
        if !self.path_exists_at(rev, path)? {
            return Ok(None);
        }
        let spec = format!("{rev}:./{}", path.display());
        let args = ["show", &spec];
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(probe_failed(&args, &self.root, &output));
        }
        Ok(Some(output.stdout))
    }

    /// The most recent commit that added `path`, if it is committed.
    pub fn commit_adding(&self, path: &Path) -> Result<Option<String>, VcsError> {
    args: &[&str],
    output: &callisto_model::CommandOutput,
) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: output.exit_code,
            stderr: output.stderr.clone(),
        },
    }
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
/// output could not be parsed into the shape this module expects.
pub(super) fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::MalformedOutput { detail: detail.into() },
    }
